CREATE TABLE IF NOT EXISTS migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces (id text PRIMARY KEY, wallet_address text UNIQUE, kind text NOT NULL CHECK(kind IN ('sample','personal','live_exercise')), state_version integer NOT NULL DEFAULT 1, data jsonb NOT NULL, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS challenges (id text PRIMARY KEY, wallet_address text NOT NULL, message text NOT NULL, expires_at timestamptz NOT NULL, used boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS plans (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, state_version integer NOT NULL, input_hash text NOT NULL, history_hash text, result jsonb NOT NULL, status text NOT NULL DEFAULT 'proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memory_records (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, record_type text NOT NULL, payload jsonb NOT NULL, payload_hash text NOT NULL, summary text NOT NULL, supersedes_id text, event_at text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'local', remote_job_id text, blob_id text, verified_at timestamptz, error text);
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', run_after timestamptz NOT NULL DEFAULT now(), lease_owner text, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS receipts (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, digest text NOT NULL, facts jsonb NOT NULL, allocated_atomic numeric(24,0) NOT NULL DEFAULT 0, UNIQUE(workspace_id,digest));
CREATE TABLE IF NOT EXISTS allocations (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, receipt_id text NOT NULL REFERENCES receipts(id), invoice_id text NOT NULL, amount_atomic numeric(24,0) NOT NULL, UNIQUE(receipt_id,invoice_id));
CREATE TABLE IF NOT EXISTS audit (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL, summary text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys (workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, route text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,route,key));
CREATE TABLE IF NOT EXISTS worker_heartbeats (id text PRIMARY KEY, seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status,run_after);
CREATE INDEX IF NOT EXISTS memory_scope ON memory_records(workspace_id,status);
CREATE INDEX IF NOT EXISTS audit_scope ON audit(workspace_id,created_at DESC);
CREATE INDEX IF NOT EXISTS plans_scope ON plans(workspace_id,created_at DESC);
INSERT INTO migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
